<script setup>import{computed,onMounted,ref}from'vue';import{request}from'../api';const data=ref({accounts:[],costs:[],alerts:[],recommendations:[]}),msg=ref('');const spend=computed(()=>data.value.costs.reduce((n,x)=>n+x.amount,0)),saving=computed(()=>data.value.recommendations.reduce((n,x)=>n+x.actualMonthlySavings,0));async function load(){try{data.value=await request('/api/finops-ops/dashboard?organizationCode=ZH-SH')}catch(e){msg.value=e.message}}async function create(){try{await request('/api/finops-ops/accounts',{method:'POST',body:JSON.stringify({organizationCode:'ZH-SH',accountCode:'CLOUD-'+Date.now(),provider:'CLOUD_PROVIDER',name:'生产云账号'})});msg.value='云账号已登记，等待管理员启用';await load()}catch(e){msg.value=e.message}}onMounted(load)</script>
<template><section class="head"><div><small>FINOPS CONTROL TOWER</small><h3>云成本经营控制台</h3><p>统一云账单、分摊、预算、异常和优化收益，推动技术与财务协作。</p></div><button @click="create">登记云账号</button></section><p class="msg" v-if="msg">{{msg}}</p><section class="metrics"><article><span>已采集成本</span><b>¥{{spend.toLocaleString()}}</b><small>当前数据窗口</small></article><article><span>开放告警</span><b>{{data.alerts.filter(x=>x.status==='OPEN').length}}</b><small>预算、异常与标签</small></article><article><span>已实现月节省</span><b>¥{{saving.toLocaleString()}}</b><small>优化措施实际收益</small></article></section><section class="board"><article><header><h4>成本风险</h4><button @click="load">刷新</button></header><div class="row" v-for="x in data.alerts" :key="x.id"><div><b>{{x.alertType}}</b><small>{{x.description}}</small></div><em>{{x.severity}}</em></div><p v-if="!data.alerts.length">当前没有成本治理告警。</p></article><article><header><h4>优化建议</h4><span>收益闭环</span></header><div class="row" v-for="x in data.recommendations" :key="x.id"><div><b>{{x.actionType}} · {{x.resourceId}}</b><small>预计 ¥{{x.estimatedMonthlySavings}} / 实际 ¥{{x.actualMonthlySavings}}</small></div><em>{{x.status}}</em></div><p v-if="!data.recommendations.length">暂无专业优化建议。</p></article></section></template>
<style scoped>.head{padding:27px 30px;border-radius:14px;background:#263b34;color:#fff;display:flex;justify-content:space-between;align-items:end}.head small{color:#a7c8b8;letter-spacing:1.4px}.head h3{font-size:25px;margin:8px 0}.head p{margin:0;color:#d0e2da}.head button{border:0;border-radius:8px;padding:11px 17px;background:#e2b15a;color:#233830;font-weight:700}.msg{padding:10px 14px;background:#f1f8f4;border-left:3px solid #4a8168}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:16px 0}.metrics article,.board article{background:#fff;border:1px solid #dde7e1;border-radius:12px;padding:18px}.metrics span,.metrics small{display:block;color:#697b71}.metrics b{display:block;font-size:28px;margin:8px 0}.board{display:grid;grid-template-columns:1fr 1fr;gap:16px}.board header,.row{display:flex;justify-content:space-between;align-items:center}.board header{padding-bottom:12px;border-bottom:1px solid #e8efeb}.board header button{border:0;background:transparent;color:#367357}.row{padding:14px 0;border-bottom:1px solid #edf2ef}.row small{display:block;color:#75827b;margin-top:4px}.row em{font-style:normal;font-size:12px;color:#3d7258}@media(max-width:800px){.head{align-items:start;flex-direction:column;gap:20px}.metrics,.board{grid-template-columns:1fr}}</style>
